import{_ as e,o as r,c as o,aa as a}from"./chunks/framework.oWfRcsIL.js";const g=JSON.parse('{"title":"Quickstart","description":"Create and run your first syslifters.ai project.","frontmatter":{"title":"Quickstart","description":"Create and run your first syslifters.ai project."},"headers":[],"relativePath":"getting-started/quickstart.md","filePath":"getting-started/quickstart.md"}'),n={name:"getting-started/quickstart.md"};function s(i,t,d,c,h,l){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="quickstart" tabindex="-1">Quickstart <a class="header-anchor" href="#quickstart" aria-label="Permalink to &quot;Quickstart&quot;">​</a></h1><p>This guide takes you from an empty project list to a report. Before you start, read the pages under <a href="/#before-you-start">Before you start</a>; they cover your responsibilities and how to avoid unwanted impact on the target.</p><h2 id="_1-sign-in" tabindex="-1">1. Sign in <a class="header-anchor" href="#_1-sign-in" aria-label="Permalink to &quot;1. Sign in&quot;">​</a></h2><p>Open syslifters.ai in your browser and sign in with your company account. You land on the <strong>Projects</strong> list.</p><h2 id="_2-create-a-project" tabindex="-1">2. Create a project <a class="header-anchor" href="#_2-create-a-project" aria-label="Permalink to &quot;2. Create a project&quot;">​</a></h2><p>Click <strong>New project</strong> and fill in the form.</p><h3 id="basics" tabindex="-1">Basics <a class="header-anchor" href="#basics" aria-label="Permalink to &quot;Basics&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Project name</strong></td><td>A name you recognise, for example &quot;Customer portal staging&quot;.</td></tr><tr><td><strong>Data residency</strong></td><td>Which models may process the project&#39;s data. See <a href="/legal/data-handling#data-residency">Data residency</a>.</td></tr><tr><td><strong>Permission mode</strong></td><td>How much the agents may do without asking you. <strong>Auto-classify actions</strong> is a good default. See <a href="/getting-started/safety-controls#permission-modes">Permission modes</a>.</td></tr><tr><td><strong>Model</strong></td><td>The AI model the agents use. Models that your data residency setting does not allow are greyed out.</td></tr><tr><td><strong>Reasoning effort</strong></td><td>Higher is more thorough, but slower and more expensive. Leave the default if unsure.</td></tr><tr><td><strong>Target types</strong></td><td><strong>Web app</strong>, <strong>API</strong> and/or <strong>Mobile (Android)</strong>.</td></tr></tbody></table><h3 id="scope-and-entry-points" tabindex="-1">Scope and entry points <a class="header-anchor" href="#scope-and-entry-points" aria-label="Permalink to &quot;Scope and entry points&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>In-scope hosts / URLs</strong></td><td>Every host the agents may test, one per line.</td></tr><tr><td><strong>Out-of-scope hosts / URLs</strong></td><td>Hosts the agents can never reach.</td></tr><tr><td><strong>Seed URLs</strong></td><td>The entry points where recon starts: login page, application, API base URL.</td></tr></tbody></table><p>If a login provider is out of scope, login requests to it never succeed and the agents cannot log in. If a payment provider is out of scope, payment requests to it never succeed.</p><p>See <a href="/legal/scope">Scope</a> for the exact syntax and how wildcards, ports and paths behave.</p><h3 id="accounts-and-context" tabindex="-1">Accounts and context <a class="header-anchor" href="#accounts-and-context" aria-label="Permalink to &quot;Accounts and context&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>What to enter</th></tr></thead><tbody><tr><td><strong>Test accounts</strong></td><td><code>username:password</code> or <code>username:api-token</code>, optionally <code>:role</code>, one per line. <code>role</code> is any label you choose (for example <code>user</code> or <code>admin</code>), not a fixed keyword. Accounts for every role, including administrators, and at least two per role. See <a href="/getting-started/test-accounts#test-accounts">Test accounts</a>.</td></tr><tr><td><strong>Notes</strong></td><td>Anything the agents should know: constraints, special flows, known quirks.</td></tr><tr><td><strong>Source ZIP / mobile app</strong></td><td>Optional. A ZIP of the application&#39;s source code helps the agents find vulnerabilities faster. For mobile projects, upload the <code>.apk</code>.</td></tr><tr><td><strong>Reference docs</strong></td><td>Optional. API specifications (for example OpenAPI files), user manuals or other documents. Agents can read them but never change them.</td></tr><tr><td><strong>Create a SysReptor project automatically</strong></td><td>Turn it on to have the report project created for you. Recommended.</td></tr></tbody></table><p>Remember that uploaded source code and documents are processed by the selected model. See <a href="/legal/data-handling">Data handling</a>.</p><p>Click <strong>Create project</strong>. The project opens in its workspace.</p><h2 id="_3-start-the-run" tabindex="-1">3. Start the run <a class="header-anchor" href="#_3-start-the-run" aria-label="Permalink to &quot;3. Start the run&quot;">​</a></h2><p>Check the <strong>Overview</strong> tab: scope, seed URLs and accounts should be what you expect. Then click <strong>Start run</strong>.</p><p>The run goes through recon, hunting, verification and reporting. You can follow it in the workspace:</p><ul><li><strong>Overview</strong>: the current phase and the project&#39;s settings.</li><li><strong>Knowledge</strong>: the documentation of the application the agents build during recon.</li><li><strong>Coverage</strong>: which test categories have been run.</li><li><strong>Findings</strong>: suspected and confirmed vulnerabilities.</li><li><strong>Agents</strong>: every agent, its status and what it is doing.</li><li><strong>Cost</strong>: the model cost of the run.</li></ul><h2 id="_4-answer-approval-requests" tabindex="-1">4. Answer approval requests <a class="header-anchor" href="#_4-answer-approval-requests" aria-label="Permalink to &quot;4. Answer approval requests&quot;">​</a></h2><p>Depending on the permission mode, agents ask for your approval before risky actions or before touching a host that is not in scope. Answer with <strong>Allow once</strong>, <strong>Allow &amp; add host</strong> or <strong>Deny</strong>. Unanswered requests are denied after about 10 minutes. See <a href="/getting-started/safety-controls#approvals">Approvals</a>.</p><h2 id="_5-review-findings" tabindex="-1">5. Review findings <a class="header-anchor" href="#_5-review-findings" aria-label="Permalink to &quot;5. Review findings&quot;">​</a></h2><p>Suspected vulnerabilities appear in the <strong>Findings</strong> tab as soon as an agent reports them. Each one is then reproduced by an independent agent from a clean session. Only reproduced vulnerabilities become confirmed findings, with the evidence (requests, responses, screenshots) attached.</p><h2 id="_6-end-the-run" tabindex="-1">6. End the run <a class="header-anchor" href="#_6-end-the-run" aria-label="Permalink to &quot;6. End the run&quot;">​</a></h2><p>The run either finishes on its own or you end it when your time box is over:</p><ul><li><strong>Pause</strong> stops all agents; <strong>Resume</strong> continues later.</li><li><strong>Stop hunting</strong> ends testing for good. Existing findings are still verified and reported. See <a href="/getting-started/safety-controls#stop-hunting">Stop hunting</a>.</li></ul><h2 id="_7-report" tabindex="-1">7. Report <a class="header-anchor" href="#_7-report" aria-label="Permalink to &quot;7. Report&quot;">​</a></h2><p>If the project has a SysReptor project, confirmed findings are written into it automatically, including screenshots. If you linked SysReptor after findings were already confirmed, use <strong>Report to SysReptor</strong> in the <strong>Findings</strong> tab to push them. Review and finalise the report in SysReptor.</p>',29)])])}const u=e(n,[["render",s]]);export{g as __pageData,u as default};
